def demo_pairs_from_text(txt):
 out=[]
 for n in range(1,5):
  pat=rf'Demo pair {n} input \((\d+)x(\d+)\):\n(.*?)\nDemo pair {n} output \((\d+)x(\d+)\):\n(.*?)(?=\n\n(?:Same instance|Feedback since)|\Z)'
  m=re.search(pat,txt,re.S)
  if m:
   a=[[int(x) for x in l.split()] for l in m.group(3).strip().splitlines()]
   b=[[int(x) for x in l.split()] for l in m.group(6).strip().splitlines()]
   if len(a)==len(b) and all(len(r)==len(a[0]) for r in a+b):out.append((n,a,b))
 return out

